import { MiddlewareHandler } from 'hono';
import { randomBytes } from 'crypto';
import { getCSPForEnvironment, CSP_POLICIES } from '../config/csp';

/**
 * Security Configuration Options
 */
interface SecurityConfig {
  /** Enable/disable CSP headers (default: true) */
  enabled?: boolean;
  /** CSP mode: 'enforce' or 'report-only' (default: 'enforce') */
  mode?: 'enforce' | 'report-only';
  /** CSP violation report URI (optional) */
  reportUri?: string;
  /** Generate nonce for inline scripts (default: false) */
  useNonce?: boolean;
}

/**
 * Generate a cryptographically secure nonce for CSP
 *
 * Nonces allow specific inline scripts to execute while blocking others.
 * Each nonce should be unique per request and included in both:
 * 1. The CSP header: script-src 'nonce-{value}'
 * 2. The script tag: <script nonce="{value}">
 *
 * @returns {string} Base64-encoded random nonce
 *
 * @example
 * const nonce = generateNonce();
 * // Use in CSP: script-src 'self' 'nonce-abc123...'
 * // Use in HTML: <script nonce="abc123...">
 */
function generateNonce(): string {
  return randomBytes(16).toString('base64');
}

/**
 * Get the appropriate CSP policy based on environment
 *
 * @param {string} env - Node environment (development, production, test)
 * @param {string} [nonce] - Optional nonce to inject into script-src
 * @returns {string} CSP policy string
 *
 * @example
 * const policy = getCSPPolicy('production');
 * // Returns strict production policy
 *
 * @example
 * const policy = getCSPPolicy('production', 'abc123');
 * // Returns policy with nonce: script-src 'self' 'nonce-abc123'
 */
function getCSPPolicy(env: string, nonce?: string): string {
  // Get policy from centralized configuration
  let policy = getCSPForEnvironment(env);

  // Inject nonce into script-src if provided
  if (nonce) {
    policy = policy.replace(
      /script-src ([^;]+)/,
      `script-src $1 'nonce-${nonce}'`
    );
  }

  return policy;
}

/**
 * Security Headers Middleware for Hono
 *
 * Adds comprehensive security headers to all responses:
 * - Content-Security-Policy (CSP): Primary XSS defense
 * - X-Frame-Options: Clickjacking protection (legacy fallback)
 * - X-Content-Type-Options: MIME sniffing prevention
 * - X-XSS-Protection: XSS filter (legacy fallback)
 *
 * Features:
 * - Environment-based CSP policies (dev vs prod)
 * - Report-only mode for testing
 * - Nonce generation for inline scripts
 * - CSP violation reporting endpoint
 * - Easy enable/disable via environment variables
 *
 * Configuration via environment variables:
 * - CSP_ENABLED: Enable/disable CSP (default: true)
 * - CSP_MODE: 'enforce' or 'report-only' (default: 'enforce')
 * - CSP_REPORT_URI: Violation reporting endpoint (optional)
 * - NODE_ENV: Determines which policy to use (development/production)
 *
 * @param {SecurityConfig} config - Optional configuration
 * @returns {MiddlewareHandler} Hono middleware function
 *
 * @example
 * // Basic usage (uses environment variables)
 * app.use('*', securityHeaders());
 *
 * @example
 * // With custom configuration
 * app.use('*', securityHeaders({
 *   enabled: true,
 *   mode: 'report-only',
 *   reportUri: '/api/csp-report'
 * }));
 *
 * @example
 * // With nonce generation (future enhancement)
 * app.use('*', securityHeaders({ useNonce: true }));
 */
export function securityHeaders(config: SecurityConfig = {}): MiddlewareHandler {
  return async (c, next) => {
    // Read configuration from environment variables or config
    const enabled = config.enabled ?? process.env.CSP_ENABLED !== 'false';
    const mode = config.mode ?? (process.env.CSP_MODE as 'enforce' | 'report-only') ?? 'enforce';
    const reportUri = config.reportUri ?? process.env.CSP_REPORT_URI;
    const useNonce = config.useNonce ?? false;
    const env = process.env.NODE_ENV ?? 'production';

    // Skip if CSP is disabled
    if (!enabled) {
      return next();
    }

    // Generate nonce if requested (future enhancement)
    const nonce = useNonce ? generateNonce() : undefined;

    // Store nonce in context for use in HTML rendering
    if (nonce) {
      c.set('cspNonce', nonce);
    }

    // Get appropriate CSP policy for environment
    let cspPolicy = getCSPPolicy(env, nonce);

    // Add report-uri if configured
    if (reportUri) {
      cspPolicy += `; report-uri ${reportUri}`;
    }

    // Set CSP header (enforce or report-only)
    const cspHeader = mode === 'report-only'
      ? 'Content-Security-Policy-Report-Only'
      : 'Content-Security-Policy';

    c.header(cspHeader, cspPolicy);

    // Additional Security Headers

    /**
     * X-Frame-Options: Prevent clickjacking
     *
     * DENY: Prevents any domain from framing the content
     *
     * Modern browsers use CSP frame-ancestors instead, but this provides
     * fallback support for older browsers.
     *
     * Equivalent to: frame-ancestors 'none' in CSP
     */
    c.header('X-Frame-Options', 'DENY');

    /**
     * X-Content-Type-Options: Prevent MIME sniffing
     *
     * nosniff: Forces browsers to respect declared Content-Type
     *
     * Prevents browsers from interpreting files as a different MIME type
     * than declared. Mitigates attacks where attacker uploads .txt file
     * that's actually JavaScript and browser executes it.
     */
    c.header('X-Content-Type-Options', 'nosniff');

    /**
     * X-XSS-Protection: Legacy XSS filter
     *
     * 1; mode=block: Enable XSS filter and block page if attack detected
     *
     * NOTE: This header is deprecated and unnecessary with strong CSP.
     * Modern browsers have removed XSS Auditor due to bypass vulnerabilities.
     * Included for legacy browser support only.
     *
     * CSP script-src is the modern, preferred XSS defense.
     */
    c.header('X-XSS-Protection', '1; mode=block');

    /**
     * Referrer-Policy: Control referrer information
     *
     * strict-origin-when-cross-origin: Send full URL for same-origin,
     * origin only for cross-origin HTTPS, nothing for HTTP
     *
     * Prevents leaking sensitive information in URLs to external sites
     * while maintaining analytics capabilities.
     */
    c.header('Referrer-Policy', 'strict-origin-when-cross-origin');

    /**
     * Permissions-Policy: Control browser features
     *
     * Restricts access to browser features and APIs:
     * - camera, microphone: Prevent unauthorized media access
     * - geolocation: Prevent location tracking
     * - payment: Prevent unauthorized payment requests
     *
     * Format: feature=(self "allowed-origin")
     * Using () to deny all by default, add 'self' if needed
     */
    c.header('Permissions-Policy', 'camera=(), microphone=(), geolocation=(), payment=()');

    await next();
  };
}

/**
 * Export helper functions for testing and advanced usage
 */
export { generateNonce, getCSPPolicy };

/**
 * Re-export CSP policies from centralized configuration
 * For backwards compatibility and testing
 */
export { CSP_POLICIES } from '../config/csp';
